15	
16	  if (mt2  == zero) {
17	    F1anom = one/two/(s45-s12) * (1.0 + s45/(s45-s12) * lnrat(-s12, -s45));
18	    return F1anom;
19	  } else {
20	    F1anom = one/two/(s45-s12) 
21	    * (one + two*mt2*loopI3(s12, 0.0, s45, mt2, mt2, mt2, musq, 0) 
22	    + (s45/(s45-s12)) 
23	    * (loopI2(s45, mt2, mt2, musq, 0) - loopI2(s12, mt2, mt2, musq, 0)));
24	  }
25	
26	  return F1anom;
27	}
